window.MG_LAZY_DATA["data/lazy/resources/security-v26-075-ef279fe9149d3ecf.json"]={sha256:"ef279fe9149d3ecf4e6cfbe36dbe96f3a776b4068c390b0b9a22e1ed59e0274a",value:{"sources":[{"id":"v26-case-dfd057d538fadb40","url":"https://falco.org/docs/reference/rules/","title":"Falco rule fields and behavior","titleEn":"Falco rule fields and behavior","publisher":"Falco","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"security-v26-075","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"security-v26-075","related":[{"id":"security-v26-076","referenceUrls":["https://kubernetes.io/docs/tasks/debug/debug-cluster/audit/"],"title":"Kubernetes Audit：事件階段、隱私與稽核完整性","titleEn":"Kubernetes Audit: stages, privacy and audit completeness","why":"用兩課的可觀察驗收條件比較模型邊界：交付24筆標籤事件、例外條件、降噪與保留率及到期回歸結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver twenty-four labeled events, exception conditions, noise and retention metrics, and expiry regression results.","difference":"將請求識別、主體、資源、動詞、時間與結果連接，避免把同一請求不同stage當成多次事件。","differenceEn":"Link request identity, subject, resource, verb, time and result without counting stages as separate requests.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["降噪率=(原誤報−新誤報)/原誤報；需同時檢查真陽性是否保留。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成事件產生24筆警示，其中8筆應調查、16筆為已核准維護；窄例外可排除12筆維護。 誤報由16降4，降噪率75%；若8筆應調查全保留，precision由8/24升至8/12。","請求覆蓋=至少有必要稽核證據的唯一auditID/已知請求；Metadata與RequestResponse資料暴露程度不同。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 已知100個合成請求，稽核有180列但只涵蓋90個auditID；10個請求完全缺席。 覆蓋率90/100=90%；180列不能宣稱180%覆蓋。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Noise reduction=(old false positives−new false positives)/old false positives, alongside true-positive retention. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Synthetic events yield twenty-four alerts: eight investigable and sixteen approved maintenance; a narrow exception removes twelve maintenance alerts. False positives fall from sixteen to four, a 75% reduction; retaining all eight true positives raises precision from 8/24 to 8/12.","Request coverage counts unique auditIDs with required evidence; Metadata and RequestResponse expose different amounts of data. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. One hundred synthetic requests produce 180 audit rows covering ninety auditIDs; ten requests are absent. Coverage is 90%, not 180% merely because there are 180 rows.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"security-v26-085","referenceUrls":["https://www.misp-project.org/warninglists/"],"title":"MISP Warning Lists：誤報提示與人工判斷","titleEn":"MISP Warning Lists: false-positive warnings and analyst judgment","why":"用兩課的可觀察驗收條件比較模型邊界：交付24筆標籤事件、例外條件、降噪與保留率及到期回歸結果。","whyEn":"Compare model boundaries using observable acceptance criteria: Deliver twenty-four labeled events, exception conditions, noise and retention metrics, and expiry regression results.","difference":"保留指標來源、清單版本與命中原因，將warning視為待判斷提示而非自動允許或自動惡意。","differenceEn":"Retain indicator source, list version and match reason, treating warnings as review prompts rather than automatic benign or malicious labels.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["降噪率=(原誤報−新誤報)/原誤報；需同時檢查真陽性是否保留。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 合成事件產生24筆警示，其中8筆應調查、16筆為已核准維護；窄例外可排除12筆維護。 誤報由16降4，降噪率75%；若8筆應調查全保留，precision由8/24升至8/12。","需情境審查比例=唯一warning命中指標/唯一輸入指標；多清單重複命中只算一次。 以下為自編合成案例，只在自己的離線文件、測試資料或明確授權的隔離環境演練；不是產品實測或生產設定。 200個唯一合成指標，清單A命中30個、B命中25個，重疊10個。 唯一warning命中30+25−10=45個，審查比例22.5%。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Noise reduction=(old false positives−new false positives)/old false positives, alongside true-positive retention. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Synthetic events yield twenty-four alerts: eight investigable and sixteen approved maintenance; a narrow exception removes twelve maintenance alerts. False positives fall from sixteen to four, a 75% reduction; retaining all eight true positives raises precision from 8/24 to 8/12.","Context-review fraction counts unique warned indicators over unique inputs; repeated list matches count once. This original synthetic case uses owned offline files, test data or an explicitly authorized isolated lab; it is not a product benchmark or a production configuration. Two hundred unique synthetic indicators yield thirty matches in list A and twenty-five in B, with ten overlapping. Unique warned indicators=30+25−10=45, giving 22.5% requiring context review.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v26-case-e792035f6caa8caa","url":"https://kubernetes.io/docs/tasks/debug/debug-cluster/audit/","title":"Kubernetes auditing","titleEn":"Kubernetes auditing","publisher":"Kubernetes","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v26-case-3cd3b9113738bfaa","url":"https://www.misp-project.org/warninglists/","title":"MISP warning lists","titleEn":"MISP warning lists","publisher":"MISP","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
